struct MockPreconditionRegistry : public IPreconditionRegistry {
    struct Spec {
        const char* name;
        PreconditionRole role;
        EvalFn evalFn;
        DescribeFn describeFn;
        void* context;
        const Edge* edges;
        uint8_t edgeCount;

        PreconditionStatus evaluate() const {
            return evalFn ? evalFn(context) : PreconditionStatus{};
        }

